const cfg = $('Decode JWT & Config').item.json;
const raw = $input.first().json;
const values = raw && raw.embedding && Array.isArray(raw.embedding.values) ? raw.embedding.values : null;
if (!values) {
  return { embedFailed: true, teacherId: cfg.teacherId };
}
return {
  teacherId: cfg.teacherId,
  studentId: cfg.studentId,
  question: cfg.question,
  topK: cfg.topK,
  embeddingLiteral: '[' + values.join(',') + ']'
};

