const q = $('Parse Question Embedding').item.json;
const chunks = $input.all().map(i => i.json);

if (chunks.length === 0) {
  return { json: { noSources: true, teacherId: q.teacherId } };
}

const contextText = chunks.map((c, i) => `[مصدر ${i + 1}] من كتاب "${c.book_title}"${c.chapter_title ? ' - ' + c.chapter_title : ''}${c.page_number ? ' - صفحة ' + c.page_number : ''}:\n${c.content}`).join('\n\n');

const prompt = `أنت مساعد معلم بيجاوب بالاعتماد فقط على المصادر (كتب/مذكرات) اللي المعلم رفعها، مش من معلوماتك العامة، إلا لو المصادر مش كافية للإجابة وقتها وضّح ده صراحة.\n\n== المصادر المتاحة ==\n${contextText}\n\n== سؤال المعلم ==\n${q.question}\n\nجاوب بالعربية، بشكل واضح ومباشر يناسب معلم محترف، واستشهد برقم المصدر [مصدر N] جنب كل معلومة أخدتها من مصدر معيّن.`;

return {
  json: {
    teacherId: q.teacherId,
    question: q.question,
    sources: chunks.map(c => ({ book_id: c.book_id, book_title: c.book_title, chapter: c.chapter_title, page: c.page_number, excerpt: c.content.slice(0, 220) })),
    geminiRequestBody: {
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      generationConfig: { temperature: 0.3, maxOutputTokens: 1200 }
    }
  }
};

