const prev = $('Build Answer Prompt').item.json;
const raw = $input.first().json;

if (raw.error) {
  return { json: { success: false, message: 'تعذّر توليد الإجابة، من فضلك حاولي مرة أخرى.' } };
}

const candidate = raw.candidates && raw.candidates[0];
const text = candidate && candidate.content && candidate.content.parts && candidate.content.parts[0] && candidate.content.parts[0].text;
if (!text) {
  return { json: { success: false, message: 'تعذّر توليد إجابة مناسبة لهذا السؤال.' } };
}

return { json: { success: true, answer: text.trim(), sources: prev.sources } };
